import { Cancellable } from "@lincode/promiselikes"
import { throttleTrailing } from "@lincode/utils"
import { GetGlobalState } from "./store"

type Context = {
    position: number
    data: Record<number, any>
    handle: Cancellable
}
const contextStack: Array<Context> = []

const getContext = () => contextStack[contextStack.length - 1]

const contextLazyMemo = <T>(value: (context: Context) => T): T => {
    const context = getContext()
    return (context.data[context.position++] ??= value(context))
}

const contextMemo = <T>(value: T): T => {
    const context = getContext()
    return (context.data[context.position++] ??= value)
}

const run = (
    handle: Cancellable,
    cleanup: (() => void) | undefined | void,
    data: Record<number, any>,
    effectBody: () => (() => void) | void
) => {
    contextStack.push({ position: 0, data, handle })
    cleanup?.()
    const nextCleanup = effectBody()
    contextStack.pop()
    return nextCleanup
}

const diffAndRun = (
    handle: Cancellable,
    cleanup: (() => void) | undefined | void,
    data: Record<number, any>,
    getStates: Array<GetGlobalState<any> | any>,
    statesOld: Array<any> | undefined,
    effectBody: () => (() => void) | void
) => {
    contextStack.push({ position: 0, data, handle })
    const states = getStates.map((s) => (typeof s === "function" ? s() : s))
    const shouldRun = !statesOld || states.some((s, i) => s !== statesOld![i])
    shouldRun && cleanup?.()
    const nextCleanup = shouldRun ? effectBody() : undefined
    contextStack.pop()

    return <const>[nextCleanup, states, shouldRun]
}

export const createNestedEffect = (
    effectBody: () => (() => void) | void,
    getStates: Array<GetGlobalState<any> | any>
) => {
    const handle = contextLazyMemo((context) =>
        context.handle.watch(new Cancellable(() => cleanupRef.current?.()))
    )
    if (handle.done) return handle

    const data: Record<number, any> = contextMemo({})

    const cleanupRef = createRef<(() => void) | undefined | void>()
    const statesOldRef = createRef<Array<any> | undefined>()

    const cleanup = cleanupRef.current
    const statesOld = statesOldRef.current

    const [nextCleanup, states, shouldRun] = diffAndRun(
        handle,
        cleanup,
        data,
        getStates,
        statesOld,
        effectBody
    )
    if (shouldRun) cleanupRef.current = nextCleanup
    statesOldRef.current = states

    return handle
}

export const createEffect = (
    effectBody: () => (() => void) | void,
    getStates: Array<GetGlobalState<any> | undefined>
) => {
    const handle = new Cancellable(() => setTimeout(() => cleanup?.()))
    const data: Record<number, any> = {}

    let cleanup: (() => void) | undefined | void
    const rerun = throttleTrailing(() => {
        if (handle.done) return
        cleanup = run(handle, cleanup, data, effectBody)
    })
    rerun()
    for (const getState of getStates) getState && handle.watch(getState(rerun))
    return handle
}

export const createRef = <T>(value?: T | (() => T)): { current: T } =>
    contextLazyMemo(() => ({
        current: typeof value === "function" ? (value as Function)() : value
    }))

export const createPrevious = <T>(value: T) => {
    const valueRef = createRef(value)

    createNestedEffect(() => {
        queueMicrotask(() => (valueRef.current = value))
    }, [value])

    return valueRef.current
}

export const createMemo = <T>(
    value: () => T,
    getStates: Array<GetGlobalState<any> | any>
) => {
    const valueRef = createRef(value)
    const firstRef = createRef(true)

    createNestedEffect(() => {
        if (firstRef.current) {
            firstRef.current = false
            return
        }
        valueRef.current = value()
    }, getStates)

    return valueRef.current
}
